from __future__ import annotations
from .record import Migration

class CircularDependencyError(Exception):
    pass

class MissingDependencyError(Exception):
    pass

class MigrationGraph:
    def __init__(self):
        self._migrations: dict[str, Migration] = {}

    def add_migration(self, migration: Migration) -> None:
        self._migrations[migration.name] = migration

    def topological_sort(self) -> list[str]:
        # Build adjacency: dependency -> dependents
        adj: dict[str, list[str]] = {name: [] for name in self._migrations}
        indegree: dict[str, int] = {name: 0 for name in self._migrations}

        for name, mig in self._migrations.items():
            for dep in mig.dependencies:
                if dep not in self._migrations:
                    raise MissingDependencyError(
                        f"Migration '{name}' depends on missing migration '{dep}'"
                    )
                adj[dep].append(name)
                indegree[name] += 1

        # Kahn's algorithm
        ready = [n for n, d in indegree.items() if d == 0]
        ready.sort()
        order: list[str] = []
        while ready:
            node = ready.pop(0)
            order.append(node)
            for dependent in sorted(adj[node]):
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    ready.append(dependent)
                    ready.sort()

        if len(order) != len(self._migrations):
            raise CircularDependencyError(
                "Circular dependency detected among migrations"
            )

        return order

