import hashlib
from typing import Any
from .record import Migration, MigrationState
from .graph import MigrationGraph

class TamperedMigrationError(Exception):
    pass

class MigrationEngine:
    def __init__(self, graph: MigrationGraph, state: MigrationState):
        self.graph = graph
        self.state = state
        self.context: dict[str, Any] = {}

    def _verify_checksum(self, migration: Migration) -> None:
        recorded = self.state.applied_migrations.get(migration.name)
        if recorded is not None and recorded != migration.checksum:
            raise TamperedMigrationError(
                f"Migration '{migration.name}' checksum mismatch: "
                f"recorded {recorded}, current {migration.checksum}"
            )

    def upgrade(self, target: str | None = None) -> list[str]:
        order = self.graph.topological_sort()

        # Determine which migrations are already applied
        applied = set(self.state.applied_migrations.keys())

        # Verify checksums of all applied migrations present in the graph
        for name in order:
            mig = self.graph._migrations[name]
            if name in applied:
                self._verify_checksum(mig)

        # Select migrations to apply up to target (inclusive)
        plan: list[str] = []
        for name in order:
            if name in applied:
                continue
            plan.append(name)
            if target is not None and name == target:
                break

        # Apply them in order
        for name in plan:
            mig = self.graph._migrations[name]
            mig.up(self.context)
            self.state.applied_migrations[name] = mig.checksum

        return plan

    def downgrade(self, target: str) -> list[str]:
        order = self.graph.topological_sort()
        applied_order = [n for n in order if n in self.state.applied_migrations]

        # Verify checksums of all applied migrations before downgrading
        for name in applied_order:
            mig = self.graph._migrations[name]
            self._verify_checksum(mig)

        # Downgrade in reverse topological order until we reach (not including) target.
        # If target is not currently applied, downgrade everything down to it.
        plan: list[str] = []
        for name in reversed(applied_order):
            if name == target:
                break
            plan.append(name)

        for name in plan:
            mig = self.graph._migrations[name]
            mig.down(self.context)
            del self.state.applied_migrations[name]

        return plan","path":"migration/engine.py"},"call_id":"call_5","name":"patch","thought":"


